function prepare({
  response,
  firstTitle,
  lastTitle,
  companyTitle,
  websiteTitle,
  baseId,
  table,
  channelId,
}) {
  if (!response || !Array.isArray(response.definition?.fields) || !Array.isArray(response.answers))
    throw Error("Invalid Typeform response");
  for (const x of [firstTitle, lastTitle, companyTitle, websiteTitle, baseId, table, channelId])
    if (typeof x !== "string" || !x.trim() || x.startsWith("YOUR_"))
      throw Error("Configure question titles and destinations");
  const get = (title, required) => {
    const f = response.definition.fields.filter((x) => x.title === title);
    if (f.length !== 1) throw Error("Question title must be unique: " + title);
    const a = response.answers.filter((x) => x.field?.id === f[0].id);
    if (a.length > 1) throw Error("Duplicate answer");
    let v = a[0]?.text ?? a[0]?.url ?? "";
    if (typeof v !== "string" || (required && !v.trim())) throw Error("Missing answer: " + title);
    return v.trim();
  };
  const first_name = get(firstTitle, true),
    last_name = get(lastTitle, true),
    company = get(companyTitle, false),
    website = get(websiteTitle, false);
  if (!company && !website) throw Error("Company or website is required");
  return {
    data: [
      { first_name, last_name, ...(company ? { company } : {}), ...(website ? { website } : {}) },
    ],
    baseId,
    table,
    channelId,
  };
}

return $input.all().flatMap((x, i) => {
  if (x.json.event_type !== "form_response") return [];
  const p = prepare({
    response: x.json.form_response,
    firstTitle: "First name",
    lastTitle: "Last name",
    companyTitle: "Company",
    websiteTitle: "Website",
    baseId: "YOUR_AIRTABLE_BASE_ID",
    table: "Contacts",
    channelId: "YOUR_SLACK_CHANNEL_ID",
  });
  return [
    {
      json: { ...p.data[0], baseId: p.baseId, table: p.table, channelId: p.channelId },
      pairedItem: { item: i },
    },
  ];
});

function enrich({ data, error, success, status }) {
  if (
    error ||
    success !== true ||
    status !== "succeeded" ||
    !Array.isArray(data) ||
    data.length !== 1
  )
    throw Error("Enrichment is incomplete");
  const x = data[0];
  if (typeof x?.full_name !== "string" || !x.full_name.trim())
    throw Error("Enriched full name is missing");
  const fields = {},
    put = (name, value) => {
      if (typeof value === "string" && value.trim()) fields[name] = value.trim();
    };
  put("firstName", x.first_name);
  put("lastName", x.last_name);
  put("linkedInProfile", x.linkedin);
  put("Email", x.email?.[0]?.email);
  put("Phone", x.phone);
  put("website", x.website);
  put("LinkedIn Company", x.company_linkedin);
  put("Industry", x.naf5_des);
  put(
    "Address",
    [x.siret_address, [x.siret_zip, x.siret_city].filter(Boolean).join(" ")]
      .filter(Boolean)
      .join(", "),
  );
  if (!fields.firstName || !fields.lastName || !fields.Email)
    throw Error("Enriched name or email is missing");
  const name = x.full_name.trim(),
    escaped = name.replace(/\\/g, "\\\\").replace(/'/g, "\\'");
  return { fields, formula: "{fullName}='" + escaped + "'" };
}

return [
  {
    json: enrich({
      data: $input.all().map((x) => x.json),
      error: false,
      success: true,
      status: "succeeded",
    }),
  },
];

function plan({ records, offset, fields }) {
  if (!Array.isArray(records) || records.length > 1 || offset)
    throw Error("Ambiguous Airtable contact match");
  if (!fields || typeof fields !== "object") throw Error("Missing fields");
  const id = records[0]?.id;
  if (records.length && (!id || typeof id !== "string")) throw Error("Invalid contact record");
  return {
    create: !records.length,
    createRecords: [{ fields }],
    updateRecords: [{ id: id ?? "unused", fields }],
    expectedId: id ?? "",
    text: records.length
      ? "🥳 An existing lead has just subscribed!"
      : "🎉 A new lead has just subscribed!",
  };
}

const a = $input
  .all()
  .map((x) => x.json)
  .filter((x) => Object.keys(x).length > 0);
const p = plan({
  records: a,
  offset: null,
  fields: $("Prepare contact fields").first().json.fields,
});
return [
  {
    json: {
      ...$("Prepare contact fields").first().json.fields,
      create: p.create,
      recordId: p.expectedId,
      text: p.text,
    },
  },
];

const p = $("Choose create or update").first().json;
return $input.all().map((x, i) => {
  if (!x.json.id || (!p.create && x.json.id !== p.recordId))
    throw Error("Airtable write not confirmed");
  return { json: { text: p.text }, pairedItem: { item: i } };
});
